    font-size:.9rem;font-weight:600;transition:all .25s;
  }
  .tabs button:hover{background:rgba(255,255,255,.3)}
  .tabs button.active{background:#fff;color:#1b3a6b;border-color:#fff}

  /* ── layout ── */
  .container{
    max-width:1280px;margin:0 auto;padding:0 1.5rem 4rem;
  }
  .section{display:none}
  .section.active{display:flex;gap:2rem}
  .col{flex:1;min-width:0}

  /* ── cards ── */
  .card{
    background:rgba(255,255,255,.92);border-radius:16px;
    padding:2rem 1.8rem;margin-bottom:2rem;
