<script>
(function(){
  /* ── section tabs ── */
  var btns = document.querySelectorAll('#tabs button');
  btns.forEach(function(btn){
    btn.addEventListener('click',function(){
      btns.forEach(function(b){b.classList.remove('active')});
      btn.classList.add('active');
      document.querySelectorAll('.panel').forEach(function(p){p.classList.remove('active')});
      document.getElementById('panel-'+btn.dataset.target).classList.add('active');
    });
  });

  /* ── particle background ── */
  var cvs = document.getElementById('particles');
  var ctx = cvs.getContext('2d');
  var pts = [];
  var COUNT = 80;

  function resize(){
    cvs.width  = window.innerWidth;
    cvs.height = window.innerHeight;
  }
  function init(){
    pts = [];
    for(var i=0;i<COUNT;i++){
      pts.push({
        x: Math.random()*cvs.width,
        y: Math.random()*cvs.height,
        r: Math.random()*1.2+0.3,
        vx: (Math.random()-0.5)*0.15,
        vy: (Math.random()-0.5)*0.15,
        a: Math.random()*0.3+0.05
      });
    }
  }
  function draw(){
    ctx.clearRect(0,0,cvs.width,cvs.height);
    for(var i=0;i<pts.length;i++){
      var p=pts[i];
      p.x+=p.vx; p.y+=p.vy;
      if(p.x<0) p.x=cvs.width;
      if(p.x>cvs.width) p.x=0;
      if(p.y<0) p.y=cvs.height;
      if(p.y>cvs.height) p.y=0;
      ctx.beginPath();
      ctx.arc(p.x,p.y,p.r,0,Math.PI*2);
      ctx.fillStyle='rgba(251,191,36,'+p.a+')';
      ctx.fill();
    }
    requestAnimationFrame(draw);
  }
  window.addEventListener('resize',function(){resize();init()});
  resize(); init(); draw();
})();
</script>
</body>
</html>
