fun formatShutterSpeed(exposureTimeNs: Long): String {
    if (exposureTimeNs <= 0) return "0s"
    val oneSecond = 1_000_000_000L
    val reciprocal = oneSecond.toDouble() / exposureTimeNs.toDouble()
    return if (reciprocal >= 1.0) {
        val rounded = Math.round(reciprocal).coerceAtLeast(1)
